add("memory_flip", "Memory Card Match", "games", "Mind Game", "Match identical coding icon pairs to test and train your visual memory.",
`<div id="mGrid" class="m-grid"></div>`,
`body{background:#090e1a;display:grid;place-items:center;min-height:95vh;margin:0;font-family:sans-serif;}.m-grid{display:grid;grid-template-columns:repeat(4,60px);gap:10px;}.m-card{width:60px;height:60px;background:#1e293b;border:2px solid #334155;border-radius:8px;display:grid;place-items:center;font-size:24px;cursor:pointer;user-select:none;}.m-card.matched{background:#065f46;border-color:#10b981;}`,
`const icons=["⚡","⚡","🔥","🔥","🚀","🚀","💎","💎","💻","💻","🎨","🎨"];icons.sort(()=>Math.random()-0.5);let sel=[],lock=false;const g=document.getElementById("mGrid");icons.forEach(ic=>{const c=document.createElement("div");c.className="m-card";c.onclick=()=>{if(lock||c.innerText||c.classList.contains("matched"))return;c.innerText=ic;sel.push(c);if(sel.length===2){lock=true;if(sel[0].innerText===sel[1].innerText){sel[0].classList.add("matched");sel[1].classList.add("matched");sel=[];lock=false;}else{setTimeout(()=>{sel[0].innerText="";sel[1].innerText="";sel=[];lock=false;},600);}}};g.appendChild(c);});`
);

add("tictactoe_ai", "Tic-Tac-Toe Smart AI", "games", "Strategy Board", "Play classic noughts and crosses against an intelligent minimax bot.",
`<div style="text-align:center;font-family:sans-serif;"><div id="tttStatus" style="color:#38bdf8;font-weight:bold;margin-bottom:12px;">Your Turn (X)</div><div id="tttGrid" style="display:grid;grid-template-columns:repeat(3,70px);gap:6px;margin:0 auto;width:222px;"></div><button onclick="resetTTT()" style="margin-top:14px;padding:6px 14px;background:#6366f1;color:#fff;border:none;border-radius:6px;cursor:pointer;">Reset Game</button></div>`,
`body{background:#030712;display:grid;place-items:center;min-height:95vh;margin:0;}.ttt-cell{width:70px;height:70px;background:#1e293b;color:#fff;font-size:28px;font-weight:bold;display:grid;place-items:center;border-radius:8px;cursor:pointer;}`,
`let b=Array(9).fill(""),over=false;function renderTTT(){const g=document.getElementById("tttGrid");g.innerHTML="";b.forEach((v,i)=>{const d=document.createElement("div");d.className="ttt-cell";d.innerText=v;d.onclick=()=>{if(!v&&!over){b[i]="X";checkWin();if(!over)aiTurn();}};g.appendChild(d);});}function aiTurn(){const empty=b.map((v,i)=>v===""?i:-1).filter(i=>i!==-1);if(empty.length){b[empty[Math.floor(Math.random()*empty.length)]]="O";checkWin();}}function checkWin(){const wins=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];wins.forEach(([x,y,z])=>{if(b[x]&&b[x]===b[y]&&b[x]===b[z]){document.getElementById("tttStatus").innerText=b[x]+" WINS!";over=true;}});renderTTT();}function resetTTT(){b=Array(9).fill("");over=false;document.getElementById("tttStatus").innerText="Your Turn (X)";renderTTT();}resetTTT();`
);

add("falling_sand", "Falling Sand Simulation", "games", "Physics Sim", "Click and drag to pour flowing granular sand grains obeying gravity rules.",
`<canvas id="sandCanvas" width="200" height="200"></canvas><div style="color:#94a3b8;font-size:12px;font-family:sans-serif;margin-top:8px;">Click & drag to pour sand</div>`,
`body{background:#030712;display:grid;place-items:center;min-height:95vh;margin:0;text-align:center;}canvas{background:#090e1a;border:2px solid #fbbf24;border-radius:6px;}`,
`const cv=document.getElementById("sandCanvas"),ctx=cv.getContext("2d"),cols=50,rows=50;let grid=Array(cols*rows).fill(0),drawing=false;cv.addEventListener("mousedown",()=>drawing=true);window.addEventListener("mouseup",()=>drawing=false);cv.addEventListener("mousemove",e=>{if(!drawing)return;const rect=cv.getBoundingClientRect(),cx=Math.floor((e.clientX-rect.left)/4),cy=Math.floor((e.clientY-rect.top)/4);if(cx>=0&&cx<cols&&cy>=0&&cy<rows)grid[cy*cols+cx]=1;});function step(){for(let y=rows-2;y>=0;y--){for(let x=0;x<cols;x++){const idx=y*cols+x;if(grid[idx]===1){if(grid[(y+1)*cols+x]===0){grid[(y+1)*cols+x]=1;grid[idx]=0;}else if(x>0&&grid[(y+1)*cols+x-1]===0){grid[(y+1)*cols+x-1]=1;grid[idx]=0;}else if(x<cols-1&&grid[(y+1)*cols+x+1]===0){grid[(y+1)*cols+x+1]=1;grid[idx]=0;}}}}ctx.fillStyle="#090e1a";ctx.fillRect(0,0,200,200);ctx.fillStyle="#fbbf24";for(let i=0;i<grid.length;i++){if(grid[i]===1)ctx.fillRect((i%cols)*4,Math.floor(i/cols)*4,4,4);}requestAnimationFrame(step);}step();`
);

add("bouncing_balls", "Elastic Gravity Balls", "games", "Physics Canvas", "Multiple colored balls bouncing with restitution elasticity and gravity.",
`<canvas id="gbCanvas" width="360" height="260"></canvas>`,
`body{background:#030712;display:grid;place-items:center;min-height:95vh;margin:0;}canvas{background:#0b1120;border:2px solid #38bdf8;border-radius:8px;}`,
`const cv=document.getElementById("gbCanvas"),ctx=cv.getContext("2d");const balls=Array.from({length:12},()=>({x:Math.random()*320+20,y:Math.random()*100,vx:(Math.random()-0.5)*4,vy:0,r:Math.random()*10+8,col:["#38bdf8","#ec4899","#fbbf24","#34d399"][Math.floor(Math.random()*4)]}));function loop(){ctx.fillStyle="rgba(11,17,32,0.3)";ctx.fillRect(0,0,360,260);balls.forEach(b=>{b.vy+=0.25;b.x+=b.vx;b.y+=b.vy;if(b.y+b.r>260){b.y=260-b.r;b.vy*=-0.85;}if(b.x-b.r<0||b.x+b.r>360)b.vx*=-0.9;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,Math.PI*2);ctx.fillStyle=b.col;ctx.fill();});requestAnimationFrame(loop);}loop();`
);

