add("ui_metric_counter", "Animated Number Metric Counter", "modern_ui", "Animated Number", "Eased number counting effect simulating real-time metric increments.",
`<div style="text-align:center;font-family:sans-serif;color:#fff;"><div style="color:#94a3b8;font-size:13px;margin-bottom:6px;">LINES OF CODE COMPILED</div><div id="counterNum" style="font-size:48px;font-weight:800;color:#38bdf8;font-family:monospace;">0</div><button onclick="startCount()" style="margin-top:14px;padding:8px 18px;background:#6366f1;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:bold;">Trigger Count Up</button></div>`,
`body{background:#090e1a;display:grid;place-items:center;min-height:95vh;margin:0;}`,
`function startCount(){let cur=0;const target=4850;const el=document.getElementById("counterNum");const iv=setInterval(()=>{cur+=Math.floor((target-cur)*0.1)+15;if(cur>=target){cur=target;clearInterval(iv);}el.innerText=cur.toLocaleString();},30);}startCount();`
);

